/**
 * G3: player clips for Mirage. The CS2 collision mesh (G2, data/geometry/mirage-geometry.bin) has no `playerclip`
 * brushes, so a jumping pawn could stand on wall tops, ledges and roofs, or walk off the playable space. This tool
 * puts the clips back where they matter: thin vertical prisms over every walkable surface a pawn could reach from the
 * playable space by walking, dropping or jumping that CS2's own nav mesh (data/source/cs2/de_mirage.nav, generated by
 * Valve from the full collision, clips included) doesn't cover. The prisms are a second G2GM mesh that the movement
 * merges into the world mesh (`combineMeshes`), so traces see them like any wall.
 *
 *   npx tsx tools/extract-clips.ts            # data/geometry/mirage-clips.bin + mirage-clips.json, docs/img/geometry-clips.jpg
 *   npx tsx tools/extract-clips.ts --check    # rebuild in memory; exit 1 if a committed file is stale
 *   npm run clips:extract                     # the first line
 *
 * Method (docs/geometry.md, "Player clips"):
 * 1. Stand levels (`standLevels`: walkable surface tops under a 32 × 32 footprint where the standing or crouched hull
 *    fits) at every 5-unit radar pixel within 64 units of a CS2 nav polygon.
 * 2. A level is **allowed** when the CS2 nav has a polygon at its height there: one at the point within NAV_EXACT_DZ
 *    (box tops, where the decimated mesh is up to ~40 off the nav), or one within NAV_NEAR_RADIUS within NAV_NEAR_DZ
 *    (the nav is eroded by Recast's agent radius and sits ~4 above the mesh). Reached by a walk (|Δz| ≤ 18) it is also
 *    allowed with a nav polygon within WALK_RADIUS at WALK_DZ (floor strips by walls that the nav erodes more).
 * 3. Flood from the ten start positions (each moved to the nearest allowed level within 64 units) through allowed
 *    levels only, by walking, dropping (to the highest level at or below a step, if the hull fits above it) and
 *    jumping (up to JUMP_UP, if the crouched hull fits raised to the upper level). A forbidden level an edge reaches is
 *    a **frontier** level: a wall top, ledge, roof or out-of-map floor a pawn could get onto.
 * 4. Under each frontier level, every walkable triangle the hull rests on is cut into PIECE_CELL-unit world cells;
 *    every piece whose own surface the nav doesn't cover (NAV_EXACT_DZ at the point, SURFACE_RADIUS at SURFACE_DZ) gets
 *    a prism: its polygon extruded straight up by CLIP_HEIGHT, or to just under the ceiling above it. Side walls that
 *    two pieces share (same edge, same top) are left out. Allowed floors are never covered, so the prisms only stand
 *    where the hull would rest on a forbidden surface: a pawn beside a low wall isn't pushed away from it.
 * 5. Validate: flood the merged mesh (world + clips) with no nav filter at all and count reachable levels the nav
 *    doesn't allow (the manifest's `validation`).
 *
 * Deterministic: pixel order, FIFO flood, sorted pieces, sorted vertices and triangles; integer quantization (1/8).
 */
import { createHash } from 'node:crypto';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import jpeg from 'jpeg-js';
import { CROUCHING_HULL, MapGeometry, STANDING_HULL, STEP_HEIGHT, TRACE_SKIN, WALKABLE_NZ, combineMeshes, decodeGeometry, encodeGeometry, type GeometryMesh, type Hull } from '../src/sim2d/geometry';
import { BIN_PATH, CS2_NAV_PATH, Cs2NavIndex, IMAGE, loadRound, pixelCentre, previewJpeg, readCs2Nav, spawnSeeds, standLevels, worldToPixel, type Cs2NavArea } from './extract-geometry';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
export const CLIPS_PATH = 'data/geometry/mirage-clips.bin';
export const CLIPS_MANIFEST_PATH = 'data/geometry/mirage-clips.json';
export const CLIPS_PREVIEW_PATH = 'docs/img/geometry-clips.jpg';
export const CLIPS_FORMAT = 'cs2-round-replay/clips@1';

/** Parameters (written into the manifest). Units are world units. */
export const CLIP_PARAMS = {
  /** Levels are computed within this distance of a CS2 nav polygon's bounding box. */
  maskGrow: 64,
  /** Highest jump onto a level (a crouch jump clears 66 with tuning.movement; 6 more for safety). */
  jumpUp: 72,
  /** A surface point is allowed with a nav polygon right at it within this height (box tops: the decimated mesh is up to ~40 off the nav there)... */
  navExactDz: 16,
  /** ... or with one within this distance (the nav is eroded by Recast's agent radius, 16) within this height. */
  navNearRadius: 24,
  navNearDz: 16,
  /** Probe spacing for navNearRadius. */
  navProbe: 4,
  /** Surfaces are cut into pieces on this world grid; a piece is classified at its centroid. */
  pieceCell: 8,
  /** Prism height above its piece, or up to just under the ceiling above it. */
  clipHeight: 512,
  ceilingGap: 0.125,
  /** Start positions are moved to the nearest allowed level within this many pixels (5 units each) and ±24 in z. */
  seedSearchPx: 13,
  seedDz: 24,
  /** Flood-and-clip rounds at most (step 4 repeats until no frontier level is left). */
  maxRounds: 8,
} as const;

function sha256(b: Uint8Array): string {
  return createHash('sha256').update(b).digest('hex');
}

function read(path: string): Uint8Array {
  return new Uint8Array(readFileSync(resolve(ROOT, path)));
}

/** "Does the CS2 nav have a polygon at this height near here?" */
export class NavCover {
  private readonly idx: Cs2NavIndex;
  private readonly offsets: [number, number][] = [];

  constructor(areas: readonly Cs2NavArea[]) {
    this.idx = new Cs2NavIndex(areas);
    const r = CLIP_PARAMS.navNearRadius;
    const d = CLIP_PARAMS.navProbe;
    for (let oy = -r; oy <= r; oy += d) for (let ox = -r; ox <= r; ox += d) if ((ox !== 0 || oy !== 0) && ox * ox + oy * oy <= r * r) this.offsets.push([ox, oy]);
    this.offsets.sort((a, b) => a[0] * a[0] + a[1] * a[1] - (b[0] * b[0] + b[1] * b[1]) || a[0] - b[0] || a[1] - b[1]);
  }

  /** Step 2: a surface point. */
  allowsSurface(x: number, y: number, z: number): boolean {
    for (const nz of this.idx.zAt(x, y)) if (Math.abs(nz - z) <= CLIP_PARAMS.navExactDz) return true;
    for (const [ox, oy] of this.offsets) for (const nz of this.idx.zAt(x + ox, y + oy)) if (Math.abs(nz - z) <= CLIP_PARAMS.navNearDz) return true;
    return false;
  }
}

/** A surface piece: a walkable world triangle cut to one pieceCell × pieceCell world cell. */
export interface ClipPiece {
  readonly tri: number;
  readonly ci: number;
  readonly cj: number;
  /** The polygon (x y z per vertex), on the triangle's plane. */
  readonly poly: readonly (readonly [number, number, number])[];
  readonly allowed: boolean;
  /** Prism top (filled in when the piece is clipped). */
  top: number;
}

/** Triangle t clipped to the rectangle [x0, x1] × [y0, y1] (Sutherland–Hodgman), or [] if nothing is left. */
function clipTriangle(g: MapGeometry, t: number, x0: number, y0: number, x1: number, y1: number): [number, number, number][] {
  const v = g.triangle(t);
  let poly: [number, number, number][] = [
    [v[0] as number, v[1] as number, v[2] as number],
    [v[3] as number, v[4] as number, v[5] as number],
    [v[6] as number, v[7] as number, v[8] as number],
  ];
  const planes: [0 | 1, number, number][] = [
    [0, 1, x0],
    [0, -1, -x1],
    [1, 1, y0],
    [1, -1, -y1],
  ];
  for (const [axis, sgn, c] of planes) {
    const out: [number, number, number][] = [];
    for (let i = 0; i < poly.length; i++) {
      const a = poly[i] as [number, number, number];
      const b = poly[(i + 1) % poly.length] as [number, number, number];
      const da = sgn * a[axis] - c;
      const db = sgn * b[axis] - c;
      if (da >= 0) out.push(a);
      if (da >= 0 !== db >= 0) {
        const f = da / (da - db);
        out.push([a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f, a[2] + (b[2] - a[2]) * f]);
      }
    }
    poly = out;
    if (poly.length < 3) return [];
  }
  return poly;
}

/**
 * The pieces a hull rests on (step 2): every walkable world triangle whose part under the footprint tops out at the
 * level's height, cut into the cells the footprint overlaps. Pieces are classified once and cached.
 */
export class Pieces {
  private readonly cache = new Map<number, ClipPiece | null>();

  constructor(
    private readonly g: MapGeometry,
    private readonly worldTriangles: number,
    private readonly nav: NavCover,
  ) {}

  private key(t: number, ci: number, cj: number): number {
    return (t * 8192 + (cj + 4096)) * 8192 + (ci + 4096);
  }

  piece(t: number, ci: number, cj: number): ClipPiece | null {
    const k = this.key(t, ci, cj);
    const hit = this.cache.get(k);
    if (hit !== undefined) return hit;
    const cell = CLIP_PARAMS.pieceCell;
    const poly = clipTriangle(this.g, t, ci * cell, cj * cell, (ci + 1) * cell, (cj + 1) * cell);
    let area = 0;
    for (let i = 1; i + 1 < poly.length; i++) {
      const a = poly[0] as [number, number, number];
      const b = poly[i] as [number, number, number];
      const d = poly[i + 1] as [number, number, number];
      area += Math.abs((b[0] - a[0]) * (d[1] - a[1]) - (b[1] - a[1]) * (d[0] - a[0])) / 2;
    }
    let out: ClipPiece | null = null;
    if (poly.length >= 3 && area >= 0.5) {
      let mx = 0;
      let my = 0;
      let mz = 0;
      for (const q of poly) {
        mx += q[0];
        my += q[1];
        mz += q[2];
      }
      const n = poly.length;
      out = { tri: t, ci, cj, poly, allowed: this.nav.allowsSurface(mx / n, my / n, mz / n), top: NaN };
    }
    this.cache.set(k, out);
    return out;
  }

  /** The support of a hull centred at (x, y) resting at z. */
  support(x: number, y: number, z: number): ClipPiece[] {
    const hw = STANDING_HULL.halfWidth;
    const cell = CLIP_PARAMS.pieceCell;
    const out: ClipPiece[] = [];
    for (const s of this.g.footprintSpans(x, y, hw, z - 0.5, z + 0.5)) {
      const t = s[3] as number;
      if (t >= this.worldTriangles || Math.abs((s[1] as number) - z) > 0.25 || (s[2] as number) < WALKABLE_NZ) continue;
      for (let cj = Math.floor((y - hw) / cell); cj * cell < y + hw; cj++) {
        for (let ci = Math.floor((x - hw) / cell); ci * cell < x + hw; ci++) {
          const p = this.piece(t, ci, cj);
          if (p !== null) out.push(p);
        }
      }
    }
    return out;
  }

  /** A level is allowed when every piece of its support is. */
  allowsLevel(x: number, y: number, z: number): boolean {
    for (const p of this.support(x, y, z)) if (!p.allowed) return false;
    return true;
  }

  /** The hull would rest on a clipped piece: it is inside a clip prism (a pawn can't get there without crossing its walls). */
  inClip(x: number, y: number, z: number, clipped: ReadonlySet<ClipPiece>): boolean {
    for (const p of this.support(x, y, z)) if (clipped.has(p)) return true;
    return false;
  }
}

/** Stand levels per radar pixel (the pixel grid of tools/extract-geometry.ts), with the flood's result. */
export interface ClipLevels {
  readonly size: number;
  /** Levels of pixel p: z[start[p] .. start[p + 1]), highest first. */
  readonly start: Int32Array;
  readonly z: Float64Array;
  readonly standing: Uint8Array;
  /** Reached by the flood (allowed). */
  readonly reach: Uint8Array;
  /** Forbidden levels an edge from a reached level leads to. */
  readonly frontier: Uint8Array;
  /** The level each reached or frontier level was first reached from (−1 for seeds and unreached ones). */
  readonly parent: Int32Array;
  readonly pixelOf: Int32Array;
  /** Where the flood started: each start position moved to its nearest allowed level. */
  readonly seeds: readonly { x: number; y: number; z: number }[];
  readonly stats: Record<string, number>;
}

/** Pixels within `grow` units of any CS2 nav polygon's bounding box. */
function navMask(areas: readonly Cs2NavArea[], grow: number): Uint8Array {
  const N = IMAGE.size;
  const mask = new Uint8Array(N * N);
  for (const a of areas) {
    let x0 = Infinity;
    let x1 = -Infinity;
    let y0 = Infinity;
    let y1 = -Infinity;
    for (let k = 0; k < a.corners.length; k += 3) {
      x0 = Math.min(x0, a.corners[k] as number);
      x1 = Math.max(x1, a.corners[k] as number);
      y0 = Math.min(y0, a.corners[k + 1] as number);
      y1 = Math.max(y1, a.corners[k + 1] as number);
    }
    const lo = worldToPixel(x0 - grow, y1 + grow);
    const hi = worldToPixel(x1 + grow, y0 - grow);
    for (let py = Math.max(0, lo.py); py <= Math.min(N - 1, hi.py); py++) for (let px = Math.max(0, lo.px); px <= Math.min(N - 1, hi.px); px++) mask[py * N + px] = 1;
  }
  return mask;
}

/**
 * Steps 1–3 on geometry `g` (the world mesh, or merged with clips). With `pieces` null nothing is filtered (every
 * level counts as allowed): the validation flood of step 5.
 */
export function floodLevels(g: MapGeometry, areas: readonly Cs2NavArea[], levelAllowed: ((x: number, y: number, z: number) => boolean) | null, seeds: readonly { x: number; y: number; z: number }[]): ClipLevels {
  const N = IMAGE.size;
  const mask = navMask(areas, CLIP_PARAMS.maskGrow);
  const start = new Int32Array(N * N + 1);
  const zs: number[] = [];
  const st: number[] = [];
  for (let p = 0; p < N * N; p++) {
    start[p] = zs.length;
    if (mask[p] !== 1) continue;
    const c = pixelCentre(p % N, Math.floor(p / N));
    for (const l of standLevels(g, c.x, c.y, g.maxZ + 1, g.minZ - 1)) {
      zs.push(l.z);
      st.push(l.standing ? 1 : 0);
    }
  }
  start[N * N] = zs.length;
  const z = Float64Array.from(zs);
  const standing = Uint8Array.from(st);
  const pixelOf = new Int32Array(zs.length);
  for (let p = 0; p < N * N; p++) for (let k = start[p] as number; k < (start[p + 1] as number); k++) pixelOf[k] = p;
  const allowedCache = new Int8Array(zs.length).fill(-1);
  const allowed = (k: number): boolean => {
    if (levelAllowed === null) return true;
    if (allowedCache[k] === -1) {
      const p = pixelOf[k] as number;
      const c = pixelCentre(p % N, Math.floor(p / N));
      allowedCache[k] = levelAllowed(c.x, c.y, z[k] as number) ? 1 : 0;
    }
    return allowedCache[k] === 1;
  };
  const reach = new Uint8Array(zs.length);
  const frontier = new Uint8Array(zs.length);
  const parent = new Int32Array(zs.length).fill(-1);
  const used: { x: number; y: number; z: number }[] = [];
  const queue: number[] = [];
  let seedsMoved = 0;
  for (const s of seeds) {
    const { px, py } = worldToPixel(s.x, s.y);
    let best = -1;
    let bestD = Infinity;
    const R = CLIP_PARAMS.seedSearchPx;
    for (let j = py - R; j <= py + R; j++) {
      for (let i = px - R; i <= px + R; i++) {
        if (i < 0 || j < 0 || i >= N || j >= N) continue;
        const d = (i - px) * (i - px) + (j - py) * (j - py);
        if (d >= bestD) continue;
        const p = j * N + i;
        for (let k = start[p] as number; k < (start[p + 1] as number); k++) {
          if (Math.abs((z[k] as number) - s.z) > CLIP_PARAMS.seedDz || !allowed(k)) continue;
          bestD = d;
          best = k;
          break;
        }
      }
    }
    if (best < 0) throw new Error(`clips: no allowed level near the start position (${s.x}, ${s.y}, ${s.z})`);
    if (bestD > 0) seedsMoved++;
    const bp = pixelOf[best] as number;
    const bc = pixelCentre(bp % N, Math.floor(bp / N));
    used.push({ x: bc.x, y: bc.y, z: z[best] as number });
    if (reach[best] === 0) {
      reach[best] = 1;
      queue.push(best);
    }
  }
  const stats = { pixels: 0, levels: zs.length, seedsMoved, walkEdges: 0, dropEdges: 0, jumpEdges: 0, frontierWalk: 0, frontierDrop: 0, frontierJump: 0 };
  for (const m of mask) stats.pixels += m;
  const targets: number[] = [];
  for (let qi = 0; qi < queue.length; qi++) {
    const k = queue[qi] as number;
    const p = pixelOf[k] as number;
    const px = p % N;
    const py = Math.floor(p / N);
    const zk = z[k] as number;
    const hull: Hull = standing[k] === 1 ? STANDING_HULL : CROUCHING_HULL;
    const cp = pixelCentre(px, py);
    for (const [dx, dy] of [
      [1, 0],
      [-1, 0],
      [0, 1],
      [0, -1],
    ] as const) {
      const qx = px + dx;
      const qy = py + dy;
      if (qx < 0 || qy < 0 || qx >= N || qy >= N) continue;
      const q = qy * N + qx;
      const cq = pixelCentre(qx, qy);
      targets.length = 0;
      // Walking or walking off a ledge: the hull comes to rest on the highest level at or below a step up.
      let landing = -1;
      for (let m = start[q] as number; m < (start[q + 1] as number); m++) if ((z[m] as number) <= zk + STEP_HEIGHT && (landing < 0 || (z[m] as number) > (z[landing] as number))) landing = m;
      if (landing >= 0) {
        const drop = zk - (z[landing] as number);
        if (drop <= STEP_HEIGHT || !g.hullBlocked(cq.x, cq.y, zk, hull)) targets.push(landing);
      }
      // Jumping up onto a level, if the crouched hull can rise to it where it stands (no ceiling in the way).
      let headroom = NaN;
      for (let m = start[q] as number; m < (start[q + 1] as number); m++) {
        const zm = z[m] as number;
        if (!(zm > zk + STEP_HEIGHT && zm - zk <= CLIP_PARAMS.jumpUp)) continue;
        if (Number.isNaN(headroom)) headroom = g.ceilingAbove(cp.x, cp.y, zk + TRACE_SKIN, STANDING_HULL.halfWidth, CLIP_PARAMS.jumpUp + CROUCHING_HULL.height + 1);
        if (headroom >= zm + CROUCHING_HULL.height && !g.hullBlocked(cp.x, cp.y, zm, CROUCHING_HULL)) targets.push(m);
      }
      for (const m of targets) {
        if (reach[m] === 1 || frontier[m] === 1) continue;
        const dz = (z[m] as number) - zk;
        const kind = Math.abs(dz) <= STEP_HEIGHT ? 'walk' : dz < 0 ? 'drop' : 'jump';
        if (kind === 'walk') stats.walkEdges++;
        else if (kind === 'drop') stats.dropEdges++;
        else stats.jumpEdges++;
        parent[m] = k;
        if (allowed(m)) {
          reach[m] = 1;
          queue.push(m);
        } else {
          frontier[m] = 1;
          if (kind === 'walk') stats.frontierWalk++;
          else if (kind === 'drop') stats.frontierDrop++;
          else stats.frontierJump++;
        }
      }
    }
  }
  let reached = 0;
  let frontierLevels = 0;
  for (let k = 0; k < zs.length; k++) {
    reached += reach[k] as number;
    frontierLevels += frontier[k] as number;
  }
  return { size: N, start, z, standing, reach, frontier, parent, pixelOf, seeds: used, stats: { ...stats, reachedLevels: reached, frontierLevels } };
}

/** Step 4: the forbidden support pieces of every frontier level (not yet in `done`), with their prism tops. */
export function clipPieces(g: MapGeometry, lv: ClipLevels, pieces: Pieces, done: Set<ClipPiece>): { pieces: ClipPiece[]; stats: Record<string, number> } {
  // g: the world mesh (ceilings for the prism tops); pieces: classified on it.
  const N = lv.size;
  const out: ClipPiece[] = [];
  let thin = 0;
  for (let p = 0; p < N * N; p++) {
    for (let k = lv.start[p] as number; k < (lv.start[p + 1] as number); k++) {
      if (lv.frontier[k] !== 1) continue;
      const c = pixelCentre(p % N, Math.floor(p / N));
      for (const pc of pieces.support(c.x, c.y, lv.z[k] as number)) {
        if (pc.allowed || done.has(pc)) continue;
        done.add(pc);
        let mx = 0;
        let my = 0;
        let zmax = -Infinity;
        for (const q of pc.poly) {
          mx += q[0];
          my += q[1];
          zmax = Math.max(zmax, q[2]);
        }
        const ceil = g.ceilingAbove(mx / pc.poly.length, my / pc.poly.length, zmax + 0.5, 3, CLIP_PARAMS.clipHeight);
        pc.top = Math.min(zmax + CLIP_PARAMS.clipHeight, ceil - CLIP_PARAMS.ceilingGap);
        if (!(pc.top > zmax + 1)) {
          thin++;
          continue;
        }
        out.push(pc);
      }
    }
  }
  out.sort((a, b) => a.tri - b.tri || a.cj - b.cj || a.ci - b.ci);
  return { pieces: out, stats: { added: out.length, thin } };
}

/** The prisms as a canonical G2GM mesh (vertices sorted by x, y, z; triangles canonical and sorted). */
export function prismMesh(pieces: readonly ClipPiece[], quant: number): { mesh: GeometryMesh; stats: Record<string, number> } {
  const qn = (v: number): number => Math.round(v * quant);
  const tris: [number, number, number][][] = [];
  const edgeKey = (a: readonly number[], b: readonly number[], top: number): string => {
    const ka = `${qn(a[0] as number)},${qn(a[1] as number)},${qn(a[2] as number)}`;
    const kb = `${qn(b[0] as number)},${qn(b[1] as number)},${qn(b[2] as number)}`;
    return (ka < kb ? `${ka}|${kb}` : `${kb}|${ka}`) + `|${qn(top)}`;
  };
  const edgeCount = new Map<string, number>();
  for (const p of pieces) for (let i = 0; i < p.poly.length; i++) {
    const k = edgeKey(p.poly[i] as readonly number[], p.poly[(i + 1) % p.poly.length] as readonly number[], p.top);
    edgeCount.set(k, (edgeCount.get(k) ?? 0) + 1);
  }
  let walls = 0;
  let caps = 0;
  for (const p of pieces) {
    const n = p.poly.length;
    const bot = p.poly.map((v): [number, number, number] => [qn(v[0]), qn(v[1]), qn(v[2])]);
    const top = p.poly.map((v): [number, number, number] => [qn(v[0]), qn(v[1]), qn(p.top)]);
    for (let i = 1; i + 1 < n; i++) {
      tris.push([top[0] as [number, number, number], top[i] as [number, number, number], top[i + 1] as [number, number, number]]);
      caps++;
    }
    for (let i = 0; i < n; i++) {
      const j = (i + 1) % n;
      if (edgeCount.get(edgeKey(p.poly[i] as readonly number[], p.poly[j] as readonly number[], p.top)) !== 1) continue;
      const a = bot[i] as [number, number, number];
      const b = bot[j] as [number, number, number];
      const c = top[j] as [number, number, number];
      const d = top[i] as [number, number, number];
      tris.push([a, b, c], [a, c, d]);
      walls += 2;
    }
  }
  // Vertices: unique, sorted by (x, y, z).
  const vkey = (v: readonly number[]): string => `${v[0] as number},${v[1] as number},${v[2] as number}`;
  const uniq = new Map<string, [number, number, number]>();
  for (const t of tris) for (const v of t) uniq.set(vkey(v), v);
  const verts = [...uniq.values()].sort((a, b) => a[0] - b[0] || a[1] - b[1] || a[2] - b[2]);
  const index = new Map<string, number>();
  verts.forEach((v, i) => index.set(vkey(v), i));
  const out: [number, number, number][] = [];
  const seen = new Set<string>();
  let degenerate = 0;
  for (const t of tris) {
    const [p, q, r] = t as [[number, number, number], [number, number, number], [number, number, number]];
    const cx = (q[1] - p[1]) * (r[2] - p[2]) - (q[2] - p[2]) * (r[1] - p[1]);
    const cy = (q[2] - p[2]) * (r[0] - p[0]) - (q[0] - p[0]) * (r[2] - p[2]);
    const cz = (q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0]);
    if (cx === 0 && cy === 0 && cz === 0) {
      degenerate++;
      continue;
    }
    let ids = [index.get(vkey(p)) as number, index.get(vkey(q)) as number, index.get(vkey(r)) as number];
    const m = ids.indexOf(Math.min(...ids));
    ids = [ids[m] as number, ids[(m + 1) % 3] as number, ids[(m + 2) % 3] as number];
    const sk = [...ids].sort((a, b) => a - b).join(',');
    if (seen.has(sk)) continue;
    seen.add(sk);
    out.push(ids as [number, number, number]);
  }
  out.sort((a, b) => a[0] - b[0] || a[1] - b[1] || a[2] - b[2]);
  const mesh: GeometryMesh = { quant, verts: Int32Array.from(verts.flat()), tris: Int32Array.from(out.flat()) };
  return { mesh, stats: { caps, walls, degenerate, vertices: verts.length, triangles: out.length } };
}

export interface ClipProducts {
  readonly bin: Uint8Array;
  readonly manifestText: string;
  readonly preview: Uint8Array;
  readonly world: MapGeometry;
  readonly merged: MapGeometry;
}

/** The world mesh merged with the committed clips (what the movement uses). */
export function loadMovementGeometry(root: string = ROOT): MapGeometry {
  const world = decodeGeometry(new Uint8Array(readFileSync(resolve(root, BIN_PATH))));
  const clips = decodeGeometry(new Uint8Array(readFileSync(resolve(root, CLIPS_PATH))));
  return new MapGeometry(combineMeshes(world, clips));
}

function previewImage(check: ClipLevels, pieces: readonly ClipPiece[]): Uint8Array {
  const N = check.size;
  const radar = jpeg.decode(readFileSync(resolve(ROOT, 'data/mirage-radar.jpg')), { useTArray: true });
  const rgba = new Uint8Array(N * N * 4);
  for (let p = 0; p < N * N; p++) {
    let reached = false;
    for (let k = check.start[p] as number; k < (check.start[p + 1] as number); k++) if (check.reach[k] === 1) reached = true;
    const f = reached ? 0.75 : 0.35;
    rgba[p * 4] = Math.round((radar.data[p * 4] as number) * f);
    rgba[p * 4 + 1] = Math.round((radar.data[p * 4 + 1] as number) * f + (reached ? 40 : 0));
    rgba[p * 4 + 2] = Math.round((radar.data[p * 4 + 2] as number) * f);
    rgba[p * 4 + 3] = 255;
  }
  for (const pc of pieces) {
    let mx = 0;
    let my = 0;
    for (const q of pc.poly) {
      mx += q[0];
      my += q[1];
    }
    const { px, py } = worldToPixel(mx / pc.poly.length, my / pc.poly.length);
    if (px < 0 || py < 0 || px >= N || py >= N) continue;
    for (const d of [0, 1, N, N + 1]) {
      const o = (py * N + px + d) * 4;
      rgba[o] = 255;
      rgba[o + 1] = 40;
      rgba[o + 2] = 40;
    }
  }
  return previewJpeg(rgba, N);
}

export function buildClips(): ClipProducts {
  const worldBytes = read(BIN_PATH);
  const navBytes = read(CS2_NAV_PATH);
  const roundBytes = read('data/round.json');
  const worldMesh = decodeGeometry(worldBytes);
  const world = new MapGeometry(worldMesh);
  const areas = readCs2Nav(navBytes).areas;
  const nav = new NavCover(areas);
  const seeds = spawnSeeds(loadRound());
  // Steps 1–4, repeated on the world mesh merged with the clips so far until no frontier level is left: a clip only
  // stops the flood where it stands, and the next round may reach new frontier beyond a gap.
  const done = new Set<ClipPiece>();
  const clipped: ClipPiece[] = [];
  const rounds: Record<string, number>[] = [];
  let first: ClipLevels | null = null;
  let merged = world;
  const pieces = new Pieces(world, world.triangleCount, nav);
  let built = prismMesh([], worldMesh.quant);
  for (let round = 0; round < CLIP_PARAMS.maxRounds; round++) {
    const levels = floodLevels(merged, areas, (x, y, zz) => pieces.allowsLevel(x, y, zz), seeds);
    first ??= levels;
    const add = clipPieces(world, levels, pieces, done);
    rounds.push({ round, ...levels.stats, ...add.stats });
    if (add.pieces.length === 0) break;
    clipped.push(...add.pieces);
    built = prismMesh(clipped, worldMesh.quant);
    merged = new MapGeometry(combineMeshes(worldMesh, built.mesh));
  }
  if (first === null) throw new Error('clips: no flood');
  const bin = encodeGeometry(built.mesh);
  // Step 5: flood the merged mesh with no nav filter, only stopped by the clips (a level resting on a clipped piece is
  // inside a prism); every level it reaches should be one the nav allows.
  const inClip = new Set<ClipPiece>(clipped);
  const check = floodLevels(merged, areas, (x, y, zz) => !pieces.inClip(x, y, zz, inClip), first.seeds);
  let leaks = 0;
  const leakCells = new Set<string>();
  for (let p = 0; p < check.size * check.size; p++) {
    const c = pixelCentre(p % check.size, Math.floor(p / check.size));
    for (let k = check.start[p] as number; k < (check.start[p + 1] as number); k++) {
      if (check.reach[k] !== 1 || pieces.allowsLevel(c.x, c.y, check.z[k] as number)) continue;
      leaks++;
      leakCells.add(`${Math.floor(c.x / 64) * 64},${Math.floor(c.y / 64) * 64},${Math.round(check.z[k] as number)}`);
    }
  }
  const manifest = {
    format: CLIPS_FORMAT,
    note: 'Player clips for G3 movement: prisms over walkable surfaces a pawn could reach that the CS2 nav does not cover (wall tops, ledges, roofs, out-of-map floors). G2GM like mirage-geometry.bin; merged into it for movement. Built by tools/extract-clips.ts; see docs/geometry.md "Player clips".',
    binary: { file: CLIPS_PATH, bytes: bin.length, sha256: sha256(bin) },
    sources: [
      { file: BIN_PATH, sha256: sha256(worldBytes) },
      { file: CS2_NAV_PATH, sha256: sha256(navBytes) },
      { file: 'data/round.json', sha256: sha256(roundBytes) },
    ],
    params: CLIP_PARAMS,
    pieces: clipped.length,
    rounds,
    mesh: built.stats,
    validation: {
      reachedLevels: check.stats['reachedLevels'],
      notAllowedByNav: leaks,
      notAllowedCells: [...leakCells].sort().slice(0, 40),
    },
  };
  const manifestText = JSON.stringify(manifest, null, 2) + '\n';
  return { bin, manifestText, preview: previewImage(check, clipped), world, merged };
}

function main(): void {
  const args = process.argv.slice(2);
  const t0 = process.hrtime.bigint();
  const p = buildClips();
  const ms = Number(process.hrtime.bigint() - t0) / 1e6;
  if (args.includes('--check')) {
    const stale: string[] = [];
    if (sha256(read(CLIPS_PATH)) !== sha256(p.bin)) stale.push(CLIPS_PATH);
    if (readFileSync(resolve(ROOT, CLIPS_MANIFEST_PATH), 'utf8') !== p.manifestText) stale.push(CLIPS_MANIFEST_PATH);
    if (stale.length > 0) {
      console.error(`stale: ${stale.join(', ')}: run npx tsx tools/extract-clips.ts`);
      process.exit(1);
    }
    console.log(`${CLIPS_PATH} and ${CLIPS_MANIFEST_PATH} are up to date (${ms.toFixed(0)} ms)`);
    return;
  }
  for (const [path, bytes] of [
    [CLIPS_PATH, p.bin],
    [CLIPS_PREVIEW_PATH, p.preview],
  ] as const) {
    mkdirSync(dirname(resolve(ROOT, path)), { recursive: true });
    writeFileSync(resolve(ROOT, path), bytes);
  }
  writeFileSync(resolve(ROOT, CLIPS_MANIFEST_PATH), p.manifestText, 'utf8');
  console.log(`wrote ${CLIPS_PATH} (${p.bin.length} bytes), ${CLIPS_MANIFEST_PATH}, ${CLIPS_PREVIEW_PATH} in ${ms.toFixed(0)} ms`);
  console.log(p.manifestText);
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) main();
